Eval-driven prompting.ejemplo:
def eval_prompt(prompt_v, dataset):
    passed = 0
    for case in dataset:
        out = call_llm(prompt_v, case["input"])
        passed += int(validate_schema(out) and judge_correct(out, case["expected"]))
    return passed / len(dataset)  # exige >= 0.92 para hacer merge

